import sys

def main():
    n = int(sys.stdin.read().strip())
    if n == 2:
        print("-1")
        print("1 2")
    else:
        # Incorrect tree for Mahmoud's algorithm
        print("1 2")
        for i in range(3, n + 1):
            print(f"{'2' if i % 2 == 0 else '1'} {i}")
        # Correct tree for Mahmoud's algorithm
        print("1 2")
        for j in range(3, n + 1):
            print(f"{'1' if j % 2 == 0 else '2'} {j}")

main()
